        local v=NOTESKIN:GetVariantNamesForNoteSkin();assert(v~=NOTESKIN.GetVariantNamesForNoteSkin(nil))
        return table.concat(b,','),#v,NOTESKIN:HasVariants(),NOTESKIN.IsNoteSkinVariant('anything')
    "#);
}

